window.CallReaderScanlinesV14=function scanlinePattern(width, height) {
    if (!(width > 0) || !(height > 0) || height > 8000)
        return [];
    var seed = 0x5191c0de;
    var random = function () {
        seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
        return seed / 4294967296;
    };
    var lines = [];
    for (var y = random() * 3; y < height; y += 1.55 + random() * 1.75) {
        lines.push({ y: y, thickness: .24 + random() * .56,
            opacity: .15 + random() * .34, bend: (random() - .5) * .55,
            start: -random() * width * .04, end: width * (1 + random() * .04) });
    }
    return lines;
};
